@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  * {
    @apply border-border;
  }

  body {
    @apply font-sans antialiased bg-background text-foreground;
  }
}

/* Estilos personalizados para la fusión de ideas */
.merge-highlight {
  box-shadow: 0 0 0 4px rgba(34, 197, 94, 0.7) !important;
  transform: scale(1.05) !important;
  transition: all 0.2s ease-in-out !important;
  z-index: 5 !important;
  border: 2px solid rgb(34, 197, 94) !important;
  background-color: rgba(34, 197, 94, 0.05) !important;
  position: relative;
}

/* Animación brillante para ideas en colisión */
.merge-highlight::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  background: linear-gradient(45deg, rgba(34, 197, 94, 0) 0%, rgba(34, 197, 94, 0.2) 50%, rgba(34, 197, 94, 0) 100%);
  background-size: 200% 200%;
  animation: merge-shimmer 1.5s ease-in-out infinite;
  pointer-events: none;
  z-index: 0;
}

@keyframes merge-shimmer {
  0% { background-position: 0% 0%; }
  50% { background-position: 100% 100%; }
  100% { background-position: 0% 0%; }
}

.merge-target {
  outline: 3px dashed rgb(34, 197, 94) !important;
  outline-offset: 3px !important;
  background-color: rgba(34, 197, 94, 0.05) !important;
  border-color: rgb(34, 197, 94) !important;
}

