      throw error;
    }
  }

  async getInvitationByToken(token: string): Promise<Invitation | undefined> {
    try {
      const result = await sql`
        SELECT * FROM invitations
        WHERE token = ${token}
        LIMIT 1
      `;

      if (result.length === 0) {
        return undefined;
      }

      const invitation = result[0];
      return {
        id: invitation.id,
        projectId: invitation.project_id,
        email: invitation.email,
        role: invitation.role,
        token: invitation.token,
        expiresAt: invitation.expires_at,
        used: invitation.used,
        createdAt: invitation.created_at
      };
    } catch (error) {
      console.error('Error getting invitation by token:', error);
      throw error;
    }
  }

  async markInvitationAsUsed(id: number): Promise<Invitation | undefined> {
    try {
      const result = await sql`
        UPDATE invitations
        SET used = true
        WHERE id = ${id}
        RETURNING *
      `;

      if (result.length === 0) {
        return undefined;
      }

      const updatedInvitation = result[0];
      return {
        id: updatedInvitation.id,
        projectId: updatedInvitation.project_id,
        email: updatedInvitation.email,
        role: updatedInvitation.role,
        token: updatedInvitation.token,
        expiresAt: updatedInvitation.expires_at,
        used: updatedInvitation.used,
        createdAt: updatedInvitation.created_at
      };
    } catch (error) {
      console.error('Error marking invitation as used:', error);
      throw error;
    }
  }

  // Implementación de updateProject para DatabaseStorage
  async updateProject(id: number, projectUpdate: Partial<InsertProject>): Promise<Project | undefined> {
    try {
      const result = await db.update(projects)
        .set(projectUpdate)
        .where(eq(projects.id, id))
        .returning();

      return result.length > 0 ? result[0] : undefined;
    } catch (error) {
      console.error('Error updating project settings:', error);
      throw error;
    }
  }

  // Idea vote operations
  async getProjectIdeaVotes(projectId: number): Promise<(IdeaVote & { user: User })[]> {
    try {
      // Realizar consulta SQL para obtener votos junto con datos de usuario
      const result = await sql`
        SELECT iv.*, u.* FROM idea_votes iv
        JOIN ideas i ON iv.idea_id = i.id
        JOIN users u ON iv.user_id = u.id
        WHERE i.project_id = ${projectId}
      `;

      // Mapear los resultados a la estructura esperada
      return result.map(row => ({
        userId: row.user_id,
        ideaId: row.idea_id,
        createdAt: row.created_at,
        user: {
          id: row.id,
          username: row.username,
          email: row.email,
          password: row.password,
          role: row.role
        }
      }));
    } catch (error) {
      console.error('Error getting project idea votes:', error);
      throw error;
    }
  }

  async getIdeaVotes(ideaId: number): Promise<IdeaVote[]> {
    try {
      const result = await db.select()
        .from(ideaVotes)
        .where(eq(ideaVotes.ideaId, ideaId));

      return result;
    } catch (error) {
      console.error('Error getting idea votes:', error);
      throw error;
    }
  }

  async getUserVotes(userId: number, projectId: number): Promise<IdeaVote[]> {
    try {
      // Realizar consulta SQL para obtener los votos del usuario en ideas del proyecto
      const result = await sql`
        SELECT iv.* FROM idea_votes iv
        JOIN ideas i ON iv.idea_id = i.id
        WHERE iv.user_id = ${userId} AND i.project_id = ${projectId}
      `;

      // Mapear los resultados a la estructura esperada
      return result.map(row => ({
        userId: row.user_id,
        ideaId: row.idea_id,
        createdAt: row.created_at
      }));
    } catch (error) {
      console.error('Error getting user votes:', error);
      throw error;
    }
  }

  async toggleIdeaVote(voteData: InsertIdeaVote): Promise<IdeaVote | undefined> {
    try {
      // Verificar si el voto ya existe
      const existingVote = await db.select()
        .from(ideaVotes)
        .where(and(
          eq(ideaVotes.userId, voteData.userId),
          eq(ideaVotes.ideaId, voteData.ideaId)
        ))
        .limit(1);

      if (existingVote.length > 0) {
        // Si el voto ya existe, eliminarlo
        await db.delete(ideaVotes)
          .where(and(
            eq(ideaVotes.userId, voteData.userId),
            eq(ideaVotes.ideaId, voteData.ideaId)
          ));

        return undefined;
      } else {
        // Si el voto no existe, crearlo
        const result = await db.insert(ideaVotes)
          .values(voteData)
          .returning();

        return result[0];
      }
    } catch (error) {
      console.error('Error toggling idea vote:', error);
      throw error;
    }
  }

  async countIdeaVotes(ideaId: number): Promise<number> {
    try {
      const countResult = await db.select({ count: sql`COUNT(*)` })
        .from(ideaVotes)
        .where(eq(ideaVotes.ideaId, ideaId));

      return Number(countResult[0].count);
    } catch (error) {
      console.error('Error counting idea votes:', error);
      throw error;
    }
  }

  async getVotingLimitForProject(projectId: number): Promise<number> {
    try {
      // Contar la cantidad de ideas en el proyecto
      const countResult = await db.select({ count: sql`COUNT(*)` })
        .from(ideas)
        .where(eq(ideas.projectId, projectId));

      const ideaCount = Number(countResult[0].count);

      // La regla es "1/3 + 1" del total de ideas
      const votingLimit = Math.floor(ideaCount / 3) + 1;

      return votingLimit;
    } catch (error) {
      console.error('Error getting voting limit for project:', error);
      throw error;
    }
  }

  // Selected ideas for connection process
  async getProjectSelectedIdeas(projectId: number): Promise<SelectedIdea[]> {
    try {
      console.log('[STORAGE] Getting all selected ideas for project:', projectId);

      // Use direct pool query instead of Drizzle
      const query = `
        SELECT * FROM selected_ideas
        WHERE project_id = $1
        ORDER BY created_at DESC
      `;

      const result = await pool.query(query, [projectId]);
      console.log('[STORAGE] Project selected ideas results:', result.rows);

      if (result.rows && result.rows.length > 0) {
        // Convert rows to our expected type with explicit type conversions
        return result.rows.map(row => ({
          id: Number(row.id),
          ideaId: Number(row.idea_id),
          projectId: Number(row.project_id),
          selectedBy: Number(row.selected_by),
          createdAt: new Date(row.created_at)
        }));
      }

      return [];
    } catch (error) {
      console.error('[STORAGE] Error getting project selected ideas:', error);
      throw error;
    }
  }

  async getSelectedIdea(ideaId: number, projectId: number): Promise<SelectedIdea | undefined> {
    try {
      console.log('[STORAGE] Getting selected idea for ideaId:', ideaId, 'projectId:', projectId);

      // Use direct pool query instead of Drizzle
      const query = `
        SELECT * FROM selected_ideas
        WHERE idea_id = $1
        AND project_id = $2
      `;

      const result = await pool.query(query, [ideaId, projectId]);
      console.log('[STORAGE] Get selected idea results:', result.rows);

      if (result.rows && result.rows.length > 0) {
        const row = result.rows[0];

        // Convert the row to our expected type with explicit type conversions
        const selectedIdea: SelectedIdea = {
          id: Number(row.id),
          ideaId: Number(row.idea_id),
          projectId: Number(row.project_id),
          selectedBy: Number(row.selected_by),
          createdAt: new Date(row.created_at)
        };

        return selectedIdea;
      }

      return undefined;
    } catch (error){
      console.error('[STORAGE] Error getting selected idea:', error);
      throw error;
    }
  }

  async toggleSelectedIdea(selectedIdeaData: InsertSelectedIdea): Promise<SelectedIdea | undefined> {
    try {
      console.log('[STORAGE] toggleSelectedIdea called with data:', JSON.stringify(selectedIdeaData, null, 2));

      // Validate the input data
      if (!selectedIdeaData.ideaId || !selectedIdeaData.projectId || !selectedIdeaData.selectedBy) {
        console.error('[STORAGE] Invalid data: Missing required fields', {
          hasIdeaId: !!selectedIdeaData.ideaId,
          hasProjectId: !!selectedIdeaData.projectId,
          hasSelectedBy: !!selectedIdeaData.selectedBy
        });
        throw new Error('Invalid data: Missing required fields for toggling idea selection');
      }

      // Use a single query with ON CONFLICT to handle both insert and delete
      // This is more robust and eliminates race conditions
      try {
        // First check if the idea is already selected
        const checkQuery = `
          SELECT * FROM selected_ideas 
          WHERE idea_id = $1 AND project_id = $2
        `;

        console.log('[STORAGE] Executing check query with params:', 
                   selectedIdeaData.ideaId, selectedIdeaData.projectId);

        const checkResult = await pool.query(checkQuery, [
          selectedIdeaData.ideaId, 
          selectedIdeaData.projectId
        ]);

        console.log('[STORAGE] Check query results:', checkResult.rows);

        // If the idea is already selected, delete it
        if (checkResult.rows.length > 0) {
          console.log('[STORAGE] Idea already selected, deleting it');

          const deleteQuery = `
            DELETE FROM selected_ideas 
            WHERE idea_id = $1 AND project_id = $2
          `;

          await pool.query(deleteQuery, [
            selectedIdeaData.ideaId, 
            selectedIdeaData.projectId
          ]);

          console.log('[STORAGE] Successfully deleted selected idea');
          return undefined;
        } 
        // Otherwise, insert it
        else {
          console.log('[STORAGE] Idea not selected, inserting it');

          const insertQuery = `
            INSERT INTO selected_ideas (idea_id, project_id, selected_by, created_at)
            VALUES ($1, $2, $3, NOW())
            RETURNING *
          `;

          const insertResult = await pool.query(insertQuery, [
            selectedIdeaData.ideaId,
            selectedIdeaData.projectId,
            selectedIdeaData.selectedBy
          ]);

          console.log('[STORAGE] Insert results:', insertResult.rows);

          if (insertResult.rows.length > 0) {
            const row = insertResult.rows[0];

            // Convert the row to our expected type with explicit type conversions
            const selectedIdea: SelectedIdea = {
              id: Number(row.id),
              ideaId: Number(row.idea_id),
              projectId: Number(row.project_id),
              selectedBy: Number(row.selected_by),
              createdAt: new Date(row.created_at)
            };

            console.log('[STORAGE] Returning new selected idea:', selectedIdea);
            return selectedIdea;
          }
        }

        return undefined;
      } catch (dbError) {
        console.error('[STORAGE] Database error in toggle operation:', dbError);
        throw dbError;
      }
    } catch (error) {
      console.error('[STORAGE] Error toggling selected idea:', error);
      throw error;
    }
  }

  async clearProjectSelectedIdeas(projectId: number): Promise<boolean> {
    try {
      console.log('[STORAGE] Clearing all selected ideas for project:', projectId);

      // Use direct pool query instead of Drizzle
      const deleteQuery = `
        DELETE FROM selected_ideas
        WHERE project_id = $1
      `;

      await pool.query(deleteQuery, [projectId]);

      console.log('[STORAGE] Successfully cleared selected ideas for project:', projectId);
      return true;
    } catch (error) {
      console.error('[STORAGE] Error clearing project selected ideas:', error);
      throw error;
    }
  }
}

// Choose between implementations based on environment variables
let storage: IStorage;

try {
  if (process.env.DATABASE_URL) {
    console.log('Using PostgreSQL database storage');
    storage = new DatabaseStorage();
  } else {
    console.log('Using in-memory storage');
    storage = new MemStorage();
  }
} catch (error) {
  console.error('Error initializing database storage, falling back to in-memory storage:', error);
  storage = new MemStorage();
}

export { storage };

